<?php
/**  * Diagnose PO Mismatch between Manager and Admin  */
require_once __DIR__ . '/backend/lib.php';
require_once __DIR__ . '/public/db_connect.php';
require_login();  $station_id = user_station_id();
?>
<!DOCTYPE html>
<html>
<head>  <title>PO Mismatch Diagnostic</title>  <style>  body { font-family: Arial; padding: 20px; background: #f5f5f5; }  .container { max-width: 1400px; margin: 0 auto; background: white; padding: 30px; border-radius: 8px; }  h1 { color: #002F6C; }  .section { margin: 30px 0; padding: 20px; border: 2px solid #e0e0e0; border-radius: 8px; }  .section h2 { color: #002F6C; margin-top: 0; }  table { width: 100%; border-collapse: collapse; margin: 15px 0; }  th { background: #002F6C; color: white; padding: 10px; text-align: left; }  td { padding: 10px; border-bottom: 1px solid #e0e0e0; }  .success { background: #d4edda; color: #155724; padding: 15px; border-radius: 5px; }  .warning { background: #fff3cd; color: #856404; padding: 15px; border-radius: 5px; }  .error { background: #f8d7da; color: #721c24; padding: 15px; border-radius: 5px; }  .badge { padding: 4px 8px; border-radius: 4px; font-size: 11px; font-weight: bold; }  .badge-pending { background: #fff3cd; color: #856404; }  .badge-approved { background: #d4edda; color: #155724; }  .badge-has-po { background: #d4edda; color: #155724; }  .badge-no-po { background: #f8d7da; color: #721c24; }  </style>
</head>
<body>  <div class="container">  <h1>Purchase Order Mismatch Diagnostic</h1>  <p style="color: #666;">This page shows the relationship between Manager's requests and Admin's POs</p>  <?php  // Get all stock requests  $stmt = $pdo->prepare("  SELECT  sr.id, sr.item_name, sr.requested_quantity, sr.approved_quantity, sr.status, sr.created_at,  po.id AS po_id, po.po_number, po.quantity AS po_quantity, po.status AS po_status  FROM stock_requests sr  LEFT JOIN purchase_orders po ON po.request_id = sr.id AND po.type = 'merch'  WHERE sr.station_id = ?  ORDER BY sr.created_at DESC  ");  $stmt->execute([$station_id]);  $all_requests = $stmt->fetchAll(PDO::FETCH_ASSOC);  $total = count($all_requests);  $pending = 0;  $approved = 0;  $rejected = 0;  $has_po = 0;  $no_po = 0;  foreach ($all_requests as $req) {  $st = strtolower($req['status']);  if (str_contains($st, 'pending')) $pending++;  elseif (str_contains($st, 'approved')) $approved++;  elseif (str_contains($st, 'rejected')) $rejected++;  if ($req['po_id']) $has_po++;  else $no_po++;  }  ?>  <!-- SUMMARY -->  <div class="section">  <h2>Summary</h2>  <table>  <tr>  <td><strong>Total Requests (Manager View):</strong></td>  <td><strong><?= $total ?></strong></td>  </tr>  <tr>  <td>├─ Pending Requests:</td>  <td><?= $pending ?></td>  </tr>  <tr>  <td>├─ Approved Requests:</td>  <td><?= $approved ?></td>  </tr>  <tr>  <td>└─ Rejected Requests:</td>  <td><?= $rejected ?></td>  </tr>  <tr style="background: #f8f9fa;">  <td><strong>Requests WITH Purchase Order:</strong></td>  <td><strong><?= $has_po ?></strong></td>  </tr>  <tr style="background: #fff3cd;">  <td><strong>Requests WITHOUT Purchase Order:</strong></td>  <td><strong><?= $no_po ?></strong></td>  </tr>  </table>  <?php if ($approved > 0 && $has_po != $approved): ?>  <div class="error" style="margin-top: 15px;">  <strong>MISMATCH DETECTED!</strong><br>  There are <?= $approved ?> approved requests but only <?= $has_po ?> have purchase orders!<br>  Expected: All <?= $approved ?> approved requests should have POs.  </div>  <?php elseif ($has_po == $approved && $approved > 0): ?>  <div class="success" style="margin-top: 15px;">  <strong>PERFECT SYNC!</strong><br>  All <?= $approved ?> approved requests have corresponding purchase orders.  </div>  <?php endif; ?>  </div>  <!-- DETAILED BREAKDOWN -->  <div class="section">  <h2>Detailed Request → PO Mapping</h2>  <table>  <thead>  <tr>  <th>Req ID</th>  <th>Item Name</th>  <th>Quantity</th>  <th>Request Status</th>  <th>Has PO?</th>  <th>PO Number</th>  <th>PO Quantity</th>  <th>PO Status</th>  <th>Date</th>  </tr>  </thead>  <tbody>  <?php foreach ($all_requests as $req): ?>  <tr>  <td><?= $req['id'] ?></td>  <td><?= htmlspecialchars($req['item_name']) ?></td>  <td><?= $req['requested_quantity'] ?></td>  <td>  <span class="badge <?= str_contains(strtolower($req['status']), 'pending') ? 'badge-pending' : 'badge-approved' ?>">  <?= htmlspecialchars($req['status']) ?>  </span>  </td>  <td>  <span class="badge <?= $req['po_id'] ? 'badge-has-po' : 'badge-no-po' ?>">  <?= $req['po_id'] ? ' YES' : ' NO' ?>  </span>  </td>  <td><?= $req['po_number'] ?: '—' ?></td>  <td><?= $req['po_quantity'] ?: '—' ?></td>  <td><?= $req['po_status'] ?: '—' ?></td>  <td><?= date('M d, Y', strtotime($req['created_at'])) ?></td>  </tr>  <?php endforeach; ?>  </tbody>  </table>  </div>  <!-- ADMIN'S VIEW -->  <?php  $admin_pos = $pdo->prepare("  SELECT po.id, po.po_number, po.product_name, po.quantity, po.status, po.created_at  FROM purchase_orders po  WHERE po.station_id = ? AND po.type = 'merch'  ORDER BY po.created_at DESC  ");  $admin_pos->execute([$station_id]);  $admin_pos_list = $admin_pos->fetchAll(PDO::FETCH_ASSOC);  ?>  <div class="section">  <h2> What Admin Sees (Purchase Orders)</h2>  <p>Total POs visible to Admin: <strong><?= count($admin_pos_list) ?></strong></p>  <?php if (count($admin_pos_list) != $has_po): ?>  <div class="warning">  <strong>DISCREPANCY!</strong><br>  Admin sees <?= count($admin_pos_list) ?> POs, but there are <?= $has_po ?> requests with POs.<br>  These numbers should match!  </div>  <?php endif; ?>  <table>  <thead>  <tr>  <th>PO ID</th>  <th>PO Number</th>  <th>Product</th>  <th>Quantity</th>  <th>Status</th>  <th>Date</th>  </tr>  </thead>  <tbody>  <?php foreach ($admin_pos_list as $po): ?>  <tr>  <td><?= $po['id'] ?></td>  <td><?= htmlspecialchars($po['po_number']) ?></td>  <td><?= htmlspecialchars($po['product_name']) ?></td>  <td><?= $po['quantity'] ?></td>  <td><?= htmlspecialchars($po['status']) ?></td>  <td><?= date('M d, Y', strtotime($po['created_at'])) ?></td>  </tr>  <?php endforeach; ?>  </tbody>  </table>  </div>  <!-- RECOMMENDATIONS -->  <div class="section">  <h2>Understanding the Numbers</h2>  <ul style="line-height: 2;">  <li><strong>Manager sees ALL requests</strong> (pending + approved + rejected)</li>  <li><strong>Only APPROVED requests</strong> should have Purchase Orders</li>  <li><strong>Pending requests</strong> don't have POs yet (they need manager approval first)</li>  <li><strong>Admin should see</strong> exactly the same number of POs as approved requests</li>  </ul>  <h3>Current Status:</h3>  <ul style="line-height: 2;">  <li>Manager has <strong><?= $total ?> total requests</strong> (<?= $pending ?> pending + <?= $approved ?> approved + <?= $rejected ?> rejected)</li>  <li>Admin sees <strong><?= count($admin_pos_list) ?> purchase orders</strong></li>  <li>Expected: Admin should see <strong><?= $approved ?> POs</strong> (one for each approved request)</li>  </ul>  <?php if (count($admin_pos_list) == $approved): ?>  <div class="success">  <strong>SYNC IS CORRECT!</strong><br>  Admin sees exactly the right number of POs matching approved requests.  </div>  <?php else: ?>  <div class="warning">  <strong>SYNC ISSUE</strong><br>  <?php if (count($admin_pos_list) < $approved): ?>  Admin sees FEWER POs than approved requests. Some approved requests may not have generated POs.  <?php else: ?>  Admin sees MORE POs than current approved requests. This includes older/historical POs.  <?php endif; ?>  </div>  <?php endif; ?>  </div>  </div>
</body>
</html>
